import{_ as t,o,c as s,a3 as a}from"./chunks/framework.C_Jzb_RY.js";const u=JSON.parse('{"title":"Dev workflow","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dev-workflow.md","filePath":"guide/dev-workflow.md","lastUpdated":1794404989000}'),n={name:"guide/dev-workflow.md"};function i(r,e,d,l,p,c){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="dev-workflow" tabindex="-1">Dev workflow <a class="header-anchor" href="#dev-workflow" aria-label="Permalink to &quot;Dev workflow&quot;">​</a></h1><p>Hot reload for Svelte and Kotlin, debugging and the dev proxy.</p><p>One command runs everything. Then open Ktor&#39;s port, not Vite&#39;s:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelteDevAll</span></span></code></pre></div><p>It starts Vite, keeps Kotlin compiling and runs your app. Save a Svelte file and the page hot reloads. Save a Kotlin file and the app restarts, and with <code>generateTs</code> on your TypeScript updates a moment later, so type errors show up in the editor right away. A restart loses anything your app keeps in memory. Stopping the task stops all three. In IntelliJ, this is the <code>Dev</code> run configuration, and each line of output is labelled <code>[vite]</code>, <code>[kotlin]</code> or <code>[app]</code>.</p><p>Once the app is listening, it prints the links you need, so they do not get lost in the output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ktor-svelte is ready. Open the app URL, not the Vite one:</span></span>
<span class="line"><span>  App:      http://localhost:8080</span></span>
<span class="line"><span>  API docs: http://localhost:8080/api/docs</span></span>
<span class="line"><span>  Vite:     http://localhost:5173</span></span></code></pre></div><p>The API docs line appears when <code>apiDocs = true</code>. After a restart it prints one line with the app URL instead. The URL comes from Ktor&#39;s <code>Responding at</code> log line, so keep Ktor&#39;s INFO logging on for the application logger.</p><p>For the edits you make most, install the live templates once with <code>./gradlew svelteLiveTemplates --install</code> and restart the IDE. In Kotlin, <code>ksget</code>, <code>kspost</code> and <code>kspage</code> write routes, and <code>ksdto</code> and <code>ksinput</code> write DTOs with bounds and rules. In TypeScript, <code>ksapi</code> calls the generated client, <code>ksload</code> writes a <code>load</code> function with <code>apiWith</code>, and <code>kserror</code> wraps code in typed error handling.</p><p>To debug your Kotlin code, start <code>Dev</code> as usual and then start the <code>Debug app</code> run configuration in debug mode. IntelliJ debugs Gradle tasks only when they run a JVM through Gradle, and <code>svelteDevAll</code> starts the app itself, so the app instead listens for a debugger on <code>127.0.0.1:5005</code> (see <code>dev.debugPort</code>). <code>Debug app</code> has auto restart on, so it reconnects after each restart. Outside IntelliJ, attach any JDWP debugger to that port. Two apps running <code>svelteDevAll</code> at once need different debug ports.</p><p>In development, API calls that take 500 ms or longer are logged with the route that served them, so you can jump straight to the code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ktor-svelte: slow API call GET /api/notes?search=milk took 812 ms (notes/Routes.kt:19)</span></span></code></pre></div><p>Change the threshold with <code>dev { slowApiCall = 200.milliseconds }</code>, or set it to <code>null</code> to turn it off. Production never logs these.</p><p>Prefer separate terminals? Run these instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelteDev</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Psvelte.dev=true</span></span></code></pre></div><p>In development mode the runtime proxies to Vite if it is reachable, otherwise serves built files if they exist, and otherwise returns a 503 explaining how to start Vite. API prefixes are never proxied.</p><p>The proxy only answers requests from this machine, so your frontend source is not open to everyone on your network, even though Ktor listens on all interfaces. Requests from elsewhere get your built files, or a 403 if there are none. It never forwards cookies or <code>Authorization</code> headers. It also refuses to start if <code>dev.url</code> points at another machine. To test from your phone or use Vite in another container, set <code>dev { allowRemote = true }</code>, and only on a network you trust.</p><p>The proxy forwards HTTP only. POST, PUT, PATCH and DELETE requests are forwarded too, with their body, so Vite endpoints and SvelteKit form actions work in dev. Paths under your API prefixes are never proxied, whatever the method. <code>server.hmr.clientPort</code> in the quick start makes Vite&#39;s client connect straight to Vite. Without it HMR still works, but the browser logs one WebSocket error before Vite falls back. Either way, the browser must be able to reach Vite&#39;s port, so a remote machine or container needs that port exposed.</p><p>With two terminals, if a Gradle process is killed rather than stopped normally, Vite or the app can keep running and hold its port. Run <code>./gradlew --stop</code>, or stop the process listening on that port. <code>svelteDevAll</code> stops its children even when its terminal is closed.</p>`,20)])])}const g=t(n,[["render",i]]);export{u as __pageData,g as default};
